def is_free(occupied, s, e):
    """Check if interval [s, e] is free"""
    for start, end in occupied:
        if not (e < start or s > end):
            return False
    return True

n = int(input())
requests = []
for _ in range(n):
    si, di = map(int, input().split())
    requests.append((si, di))

occupied = []
for si, di in requests:
    e = si + di - 1
    if is_free(occupied, si, e):
        occupied.append((si, e))
        print(si, e)
    else:
        # Find earliest x such that days x to x+di-1 are free
        x = 1
        found = False
        while True:
            current_end = x + di - 1
            if is_free(occupied, x, current_end):
                occupied.append((x, current_end))
                print(x, current_end)
                found = True
                break
            x += 1
"}

