import sys

def solve():
    s = sys.stdin.read().strip()
    n = len(s)
    # We need to find k (0 <= k <= n) such that first k are uppercase, rest lowercase
    # Cost: sum over i: if i < k: cost += 0 if s[i] == 'A' or 'B'... else 1
    #        if i >= k: cost += 0 if s[i] == 'a' or 'b'... else 1
    # We can precompute cost for each k by scanning
    min_cost = float('inf')
    for k in range(n + 1):
        cost = 0
        for i in range(k):
            if not s[i].isupper():
                cost += 1
        for i in range(k, n):
            if not s[i].islower():
                cost += 1
        min_cost = min(min_cost, cost)
    print(min_cost)

if __name__ == '__main__':
    solve()
"}

