import sys

s = sys.stdin.readline().strip()

min_actions = float('inf')
for i in range(len(s) + 1):
    # prefix of length i must be uppercase
    cost_prefix = 0
    for j in range(i):
        if s[j].islower():
            cost_prefix += 1
    # suffix from i to end must be lowercase
    cost_suffix = 0
    for j in range(i, len(s)):
        if s[j].isupper():
            cost_suffix += 1
    total = cost_prefix + cost_suffix
    min_actions = min(min_actions, total)

print(min_actions)
"}

{"code": "
MOD = 10**9 + 7

def solve():
    import sys
    input = sys.stdin.read().split()
    data = list(map(int, input))

    q = data[0]
    cases = data[1:]

    # Precompute smallest prime factor (SPF) for numbers up to 10^6
    max_x = 10**6
    spf = list(range(max_x + 1))
    for i in range(2, int(max_x**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, max_x + 1, i):
                if spf[j] == j:
                    spf[j] = i

    # Precompute factorials up to 2*10^6 + 1
    max_fact = 2 * 10**6 + 5
    fact = [1] * (max_fact)
    for i in range(1, max_fact):
        fact[i] = fact[i-1] * i % MOD

    def factorial(n):
        """Get n! modulo MOD"""
        if n < 0:
            return 0
        return fact[n]

    def modinv(n):
        """Modular inverse using Fermat's little theorem"""
        return pow(n, MOD - 2, MOD)

    def comb(n, k):
        """Binomial coefficient C(n, k) modulo MOD"""
        if n < k or k < 0:
            return 0
        return fact[n] * modinv(fact[k] * fact[n - k] % MOD) % MOD

    results = []
    for i in range(0, q * 2, 2):
        x = cases[i]
        y = cases[i + 1]

        if y == 0:
            results.append(0)
            continue

        res = 1

        # Factor x using SPF
        temp = x
        if temp > 1:
            factors = {}
            while temp > 1:
                p = spf[temp]
                count = 0
                while temp % p == 0:
                    temp //= p
                    count += 1
                factors[p] = count

            for p, cnt in factors.items():
                res = res * comb(cnt + y - 1, y - 1) % MOD

        # Multiply by 2^(y-1)
        res = res * pow(2, y - 1, MOD) % MOD

        results.append(res)

    sys.stdout.write("\n".join(map(str, results)))

if __name__ == "__main__":
    solve()
"}

