# Set of busy days
busy = set()

for i in range(n):
    s, d = map(int, input().split())
    e = s + d - 1  # End day (inclusive)

    # Check if preferred slot [s, e] is free
    is_free = True
    for day in range(s, e + 1):
        if day in busy:
            is_free = False
            break

    if is_free:
        # Use preferred slot
        print(s, e)
        for day in range(s, e + 1):
            busy.add(day)
    else:
        # Find earliest available slot of length d
        x = 1
        while True:
            # Check if [x, x+d-1] is free
            is_free = True
            for day in range(x, x + d):
                if day in busy:
                    is_free = False
                    break

            if is_free:
                print(x, x + d - 1)
                for day in range(x, x + d):
                    busy.add(day)
                break

            x += 1
