def solve():
    n, r = map(int, input().split())

    # Generate all valid points within distance r
    points = []
    for x in range(-r, r + 1):
        for y in range(-r, r + 1):
            if x * x + y * y <= r * r:
                points.append((x, y))

    # Find all pairs of points that are diametrically opposite (i.e., sum to zero)
    diametrically_opposite = []
    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            if points[i][0] + points[j][0] == 0 and points[i][1] + points[j][1] == 0:
                diametrically_opposite.append((points[i], points[j]))

    # Try different ways to distribute towers between diametrically opposite points
    max_sum = 0
    best_positions = []

    # Try placing k towers at one point and n-k towers at its diametrically opposite point
    for k in range(1, n):
        for (p1, p2) in diametrically_opposite:
            # Place k towers at p1 and n-k towers at p2
            positions = [p1] * k + [p2] * (n - k)

