def solve_robot_problem(s):
    # Calculate final position without obstacle
    x, y = 0, 0
    for c in s:
        if c == 'L':
            x -= 1
        elif c == 'R':
            x += 1
        elif c == 'D':
            y -= 1
        elif c == 'U':
            y += 1

    # If already at (0, 0), no obstacle needed
    if x == 0 and y == 0:
        return (0, 0)

    # Try placing obstacle at current final position
    # The obstacle blocks the robot from reaching (x, y)
    # This effectively cancels the last move that led to (x, y)
    # Let's try placing obstacle at (x, y)

    # Simulate with obstacle at (x, y)
    robot_x, robot_y = 0, 0
    for c in s:
        if c == 'L' and robot_x - 1 == x and robot_y == y:
            continue  # Hit obstacle
        elif c == 'R' and robot_x + 1 == x and robot_y == y:
            continue  # Hit obstacle
        elif c == 'D' and robot_y - 1 == y and robot_x == x:
            continue  # Hit obstacle
        elif c == 'U' and robot_y + 1 == y and robot_x == x:
            continue  # Hit obstacle

        # Otherwise, move
        if c == 'L':
            robot_x -= 1
        elif c == 'R':
            robot_x += 1
        elif c == 'D':
            robot_y -= 1
        elif c == 'U':
            robot_y += 1

