def solve_robot_problem(s):
    # Calculate final position without obstacle
    x, y = 0, 0
    for c in s:
        if c == 'L':
            x -= 1
        elif c == 'R':
            x += 1
        elif c == 'D':
            y -= 1
        elif c == 'U':
            y += 1

    # If already at (0, 0), no obstacle needed
    if x == 0 and y == 0:
        return (0, 0)

    # Try placing obstacle at the final position
    robot_x, robot_y = 0, 0
    for c in s:
        if robot_x == x and robot_y == y:
            continue  # Hit obstacle

        # Otherwise, move
        if c == 'L':
            robot_x -= 1
        elif c == 'R':
            robot_x += 1
        elif c == 'D':
            robot_y -= 1
        elif c == 'U':
            robot_y += 1

    if robot_x == 0 and robot_y == 0:
        return (x, y)

    # Try placing obstacle at (x+1, y)
    robot_x, robot_y = 0, 0
    for c in s:
        if robot_x == x + 1 and robot_y == y:
            continue  # Hit obstacle

        # Otherwise, move
        if c == 'L':
            robot_x -= 1
        elif c == 'R':
            robot_x += 1
        elif c == 'D':
            robot_y -= 1
        elif c == 'U':
            robot_y += 1

    if robot_x == 0 and robot_y == 0:
        return (x + 1, y)

    # Try placing obstacle at (x, y+1)
    robot_x, robot_y = 0, 0
    for c in s:
        if robot_x == x and robot_y == y + 1:
            continue  # Hit obstacle

        # Otherwise, move
        if c == 'L':
            robot_x -= 1
        elif c == 'R':
            robot_x += 1
        elif c == 'D':
            robot_y -= 1
        elif c == 'U':
            robot_y += 1

    if robot_x == 0 and robot_y == 0:
        return (x, y + 1)

    # Try placing obstacle at (x-1, y)
    robot_x, robot_y = 0, 0
    for c in s:
        if robot_x == x - 1 and robot_y == y:
            continue  # Hit obstacle

        # Otherwise, move
        if c == 'L':
            robot_x -= 1
        elif c == 'R':
            robot_x += 1
        elif c == 'D':
            robot_y -= 1
        elif c == 'U':
            robot_y += 1

    if robot_x == 0 and robot_y == 0:
        return (x - 1, y)

    # Try placing obstacle at (x, y-1)
    robot_x, robot_y = 0, 0
    for c in s:
        if robot_x == x and robot_y == y - 1:
