def solve():
    n = int(input())
    a = list(map(int, input().split()))
    a.sort()

    # Count outcomes for each round
    def count_win(round_condition, a):
        win = 0
        for i in range(n):
            for j in range(n):
                if i != j and round_condition(a[i], a[j]):
                    win += 1
        return win

    andrew_win = count_win(lambda x, y: x > y, a)
    jerry_win = count_win(lambda x, y: x < y, a)

    # Use dictionaries to track possible totals and their counts
    from collections import defaultdict

    # After round 1: Andrew wins
    dp1 = defaultdict(int)
    for i in range(n):
        for j in range(n):
            if a[i] > a[j]:
                dp1[a[i]] += 1
                dp1[a[j]] += 1

    # After round 2: Andrew wins again
    dp2 = defaultdict(int)
    for (andrew1, jerry1), count in dp1.items():
        for i in range(n):
            for j in range(n):
                if a[i] > a[j]:
                    andrew2 = andrew1 + a[i]
                    jerry2 = jerry1 + a[j]
                    dp2[(andrew2, jerry2)] += count

    # After round 3: Jerry wins
    dp3 = defaultdict(int)
    for (andrew2, jerry2), count in dp2.items():
        for i in range(n):
            for j in range(n):
                if a[i] < a[j]:
                    andrew3 = andrew2 + a[i]
                    jerry3 = jerry2 + a[j]
                    # Check if Jerry has a higher total
