def matrix_mult(a, b, mod):
    """Multiply two matrices a and b under mod."""
    n = len(a)
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        for k in range(n):
            if a[i][k] == 0:
                continue
            for j in range(n):
                result[i][j] = (result[i][j] + a[i][k] * b[k][j]) % mod
    return result


def matrix_pow(mat, power, mod):
    """Raise matrix to the power using binary exponentiation."""
    n = len(mat)
    result = [[1 if i == j else 0 for j in range(n)] for i in range(n)]  # Identity matrix
    while power > 0:
        if power % 2 == 1:
            result = matrix_mult(result, mat, mod)
        mat = matrix_mult(mat, mat, mod)
        power //= 2
    return result


def solve() -> None:
    n, b, k, x = map(int, input().split())
    digits = list(map(int, input().split()))

    # Count occurrences of each digit (0-9)
    count = [0] * 10
    for d in digits:
        count[d] += 1

    # Build transition matrix for one block
    trans = [[0] * x for _ in range(x)]
    for r in range(x):
        for d in range(10):
            if count[d] == 0:
                continue
            new_r = (d * 10 + r) % x
            trans[r][new_r] = (trans[r][new_r] + count[d]) % (10**9 + 7)

    # Raise transition matrix to the power b
    trans_pow = matrix_pow(trans, b, 10**9 + 7)

    # Initial state: before any blocks, remainder is 0
    state = [0] * x
    state[0] = 1  # Only one way to have remainder 0 with no blocks

    # Multiply state by transition^b
    ans = 0
    for i in range(x):
        ans = (ans + state[i] * trans_pow[i][k]) % (10**9 + 7)

    print(ans)

solve()
