def update_segment_tree(node, start, end, tree, l, r, val):
    """Update segment tree with value val in range [l, r]"""
    if r < start or l > end:
        return
    if l <= start and end <= r:
        tree[node] = val
        return
    mid = (start + end) // 2
    update_segment_tree(2*node, start, mid, tree, l, r, val)
    update_segment_tree(2*node+1, mid+1, end, tree, l, r, val)
    tree[node] = min(tree[2*node], tree[2*node+1])


def query_segment_tree(node, start, end, tree, l, r):
    """Query segment tree for min in range [l, r]"""
    if r < start or l > end:
        return float('inf')
    if l <= start and end <= r:
        return tree[node]
    mid = (start + end) // 2
    return min(
        query_segment_tree(2*node, start, mid, tree, l, r),
        query_segment_tree(2*node+1, mid+1, end, tree, l, r)
    )


def solve() -> None:
