            # Compute next g_i
            g0 = (g0 * x + y) % z
            index += 1
        matrix.append(row)

    # Build 1D segment tree for rows
    row_size = n
    tree = [0] * (4 * row_size)

    # Update segment tree with row minima
    for i in range(row_size):
