{"code": "
def solve():
    n = int(input())
    a = list(map(int, input().split()))  # cards in hands
    b = list(map(int, input().split()))  # cards in pile (top to bottom)

    # Find the position of each numbered card in the pile
    pile_pos = {}
    for i in range(n):
        if b[i] != 0:
            pile_pos[b[i]] = i

    # We want to get cards 1..n into the pile in order
    # Start with card 1 at the top

    # Find the current position of card 1 in the pile
    if 1 in pile_pos:
        pos_1 = pile_pos[1]
    else:
        pos_1 = -1

    # Calculate moves needed to get card 1 to the top
    moves = 0

    if pos_1 != 0 and pos_1 != -1:
        # Card 1 is not at the top
        moves += pos_1

    # Now we need to get cards 2..n into position
    for i in range(2, n + 1):
        if i not in pile_pos:
            # Card i is missing from the pile, we need to get it
            moves += 2  # Play empty card to draw i, then play i
        else:
            # Calculate how many cards are between i and the bottom
            # We need to move them out of the way
            if i == 2:
                # After card 1 is at the top, we want to get card 2
                if pos_1 == -1:
                    # Card 1 is missing, we need to get it first
                    moves += 2
                moves += n - 1 - pile_pos[i]
            else:
                moves += n - 1 - pile_pos[i]

    print(moves)

solve()
