    data = iter(input)

    t = int(next(data))

    for _ in range(t):
        n = int(next(data))
        m = int(next(data))
        a = int(next(data))
        b = int(next(data))

        graph = [[] for _ in range(n + 1)]

        for _ in range(m):
            u = int(next(data))
            v = int(next(data))
            graph[u].append(v)
            graph[v].append(u)

        def dfs(start, avoid):
            visited = [False] * (n + 1)
            stack = [start]
            visited[start] = True

            while stack:
                node = stack.pop()
                for neighbor in graph[node]:
                    if neighbor == avoid:
                        continue
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)

            return sum(visited)

        # Nodes reachable from a without going through b
        count_a = dfs(a, b)
        # Nodes reachable from b without going through a
        count_b = dfs(b, a)

        # The answer is the number of pairs that require both a and b
        # This means: one node is in the component with b when a is removed
        # and the other node is in the component with a when b is removed

        # But we also need to ensure they are in different components when both are removed

        # Get all nodes except a and b
        all_nodes = set(range(1, n + 1))
        all_nodes.discard(a)
        all_nodes.discard(b)

        # Nodes reachable from a without going through b (excluding a, b)
        set_a = set()
        stack = [a]
        visited_a = {a}
        while stack:
            node = stack.pop()
            for neighbor in graph[node]:
                if neighbor == b:
                    continue
                if neighbor not in visited_a:
                    visited_a.add(neighbor)
                    set_a.add(neighbor)
                    stack.append(neighbor)

        # Nodes reachable from b without going through a (excluding a, b)
        set_b = set()
        stack = [b]
        visited_b = {b}
        while stack:
            node = stack.pop()
            for neighbor in graph[node]:
                if neighbor == a:
                    continue
                if neighbor not in visited_b:
                    visited_b.add(neighbor)
                    set_b.add(neighbor)
                    stack.append(neighbor)

        # Count nodes in each set
        count_set_a = len(set_a)
        count_set_b = len(set_b)

        # The answer is the number of pairs (x, y) where x is in set_a and y is in set_b
        # but we also need to exclude pairs that are in the same component when both are removed

        # Get component when both are removed
        removed = {a, b}
        components = []
        for node in all_nodes:
