            # Found a non-empty sheet, check if we can place here
            # To maintain non-decreasing, we need sheets[i-1] <= pi <= sheets[i]
            if i == 0:
                # First sheet, just place it
                pos = i
                break
            elif sheets[i - 1] <= pi <= sheets[i]:
                pos = i
                break

