                # This sheet has a number, check if it violates order
                if i < n - 1 and sheets[i] > pi:
                    # pi is smaller than the current number at this position
                    # This is a violation; we should overwrite this position
                    pos = i
                    break

        # If no violation found, place at first empty position
        if pos == -1:
