def parse_path(path):
    """Parse a file path into components."""
    # Remove the disk name part
    parts = path[2:].split('\')
    disk = path[0]

    # Split into folders and file
    file_index = parts.index('.txt')
    if file_index == -1:
        raise ValueError("Invalid file path")

    folders = parts[:file_index]
    file_name = parts[file_index]

    return disk, folders, file_name


def count_subfolders(node):
    """Count all subfolders (descendants) of a node."""
    count = 0
    for child in node['subfolders']:
        count += 1 + count_subfolders(node['subfolders'][child])
    return count


def count_files(node):
    """Count all files in subtree."""
    return node.get('files', 0) + sum(count_files(node['subfolders'][child]) for child in node['subfolders'])


def main():
    import sys
    data = sys.stdin.read().strip().split('\n')

    # Dictionary of trees for each disk
    trees = {}

    max_subfolders = 0
    max_files = 0

    for line in data:
        line = line.replace('\', '\\')  # Escape backslashes for parsing
        path = line.strip()

        disk, folders, file_name = parse_path(path)

        if disk not in trees:
            trees[disk] = {
                'root': {'subfolders': {}, 'files': 0},
                'nodes': {}  # Map of folder strings to nodes
            }

        current_tree = trees[disk]
        current_node = current_tree['root']

        # Traverse through folders
        for folder in folders:
            if folder not in current_node['subfolders']:
                current_node['subfolders'][folder] = {
                    'subfolders': {},
                    'files': 0
                }
                current_node['nodes'][folder] = current_node['subfolders'][folder]

            current_node = current_node['subfolders'][folder]

        # Increment file count at the deepest folder
        current_node['files'] += 1

        # Update max values
        if current_node['files'] > max_files:
            max_files = current_node['files']

        # Count subfolders for all ancestors
        for node in current_tree['nodes'].values():
            subfolder_count = count_subfolders(node)
            if subfolder_count > max_subfolders:
                max_subfolders = subfolder_count

    print(f"{max_subfolders} {max_files}")

if __name__ == "__main__":
    main()
