    for i in range(n):  # i goes from 0 to n-1
        for j in range(m):  # j goes from 0 to m-1
            # If the cell is 1, we need to flip it
            if grid[i][j] == '1':
                # Flip (i, j), (i, j+1), (i+1, j)
                if i+1 < n and j+1 < m:
                    ops.append((i+1, j+1, i+1, j+2, i+2, j+1))
                elif i+1 < n:
                    ops.append((i+1, j+1, i+1, j+2, i+2, j))
                elif j+1 < m:
                    ops.append((i+1, j+1, i+1, j+2, i+2, j+1))
                else:
                    # Bottom-right corner, flip (i, j), (i, j-1), (i-1, j)
                    ops.append((i, j, i, j-1, i-1, j))

                # Actually perform the flip
                grid[i][j] = '0' if grid[i][j] == '1' else '1'
                if j+1 < m and i+1 < n:
                    grid[i][j+1] = '0' if grid[i][j+1] == '1' else '1'
