import sys

def is_subsequence(subseq, a, next_pos, l, r):
    """Check if subseq is a subsequence of a[l..r] using precomputed next_pos."""
    i = l - 1
    for val in subseq:
        # Find the next occurrence of val in a starting from i
        pos = next_pos[val]
        while pos <= r:
            if i < pos:
                i = pos
                break
            else:
                # No more occurrences in [l, r]
                return False
        else:
            return False
    return True

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    q = int(next(it))

    p = [int(next(it)) for _ in range(n)]
    a = [int(next(it)) for _ in range(m)]

    # Precompute next occurrence of each value
    next_pos = {}
    for i in range(m):
        val = a[i]
        if val not in next_pos:
            next_pos[val] = i
        else:
            next_pos[val] = i

    # For each query
    res = []
    for _ in range(q):
        l = int(next(it))
        r = int(next(it))
        found = False
        for i in range(n):
            # Check cyclic shift starting at i
            cyclic_p = p[i:] + p[:i]
            if is_subsequence(cyclic_p, a, next_pos, l, r):
                found = True
                break
        res.append('1' if found else '0')
    print(''.join(res))

if __name__ == '__main__':
    solve()
"}

