# Compute initial S
S = 0
for i in range(n):
    if i % 2 == 0:
        S += a[i] - b[i]
    else:
        S -= a[i] - b[i]

# For n odd, T = number of +1 terms in the alternating sum
T = (n + 1) // 2  # ceil(n/2)

# Function to compute min f(j)
def get_min_f(S, T, max_j):
    if T == 0:
        return abs(S)

    # f(j) = |S + T*j|
    # We want min |S + T*j| for j in [0, max_j]

    # If -S is within [0, max_j], min = 0
    if -S >= 0 and -S <= max_j:
        return 0

    # Otherwise, find closest endpoint
    return min(abs(S), abs(max_j + S))

max_j = m - n
print(get_min_f(S, T, max_j))

