        visited_a = [False] * (n + 1)
        components_a = []
        for i in range(1, n + 1):
            if i == a:
                continue
            if not visited_a[i]:
                stack = [i]
                visited_a[i] = True
                component = set()
                while stack:
                    node = stack.pop()
                    component.add(node)
                    for neighbor in graph[node]:
                        if neighbor != a and not visited_a[neighbor]:
                            visited_a[neighbor] = True
                            stack.append(neighbor)
                components_a.append(component)

