def matrix_mult(a, b, x):
    """Multiply two matrices of size x by x"""
    result = [[0] * x for _ in range(x)]
    for i in range(x):
        for k in range(x):
            if a[i][k]:
                for j in range(x):
                    result[i][j] = (result[i][j] + a[i][k] * b[k][j]) % MOD
    return result

def matrix_pow(mat, power, x):
    """Raise matrix to a power using exponentiation by squaring"""
    result = [[1 if i == j else 0 for j in range(x)] for i in range(x)]  # identity matrix
    while power > 0:
        if power % 2 == 1:
            result = matrix_mult(result, mat, x)
        mat = matrix_mult(mat, mat, x)
        power //= 2
    return result

def solve():
    n, b, k, x = map(int, input().split())
    digits = list(map(int, input().split()))

    # Count occurrences of each digit
    count = [0] * 10
    for d in digits:
        count[d] += 1

    # Build transition matrix
    trans = [[0] * x for _ in range(x)]
    for i in range(x):
        for d in range(1, 10):
            if count[d]:
                new_mod = (i * 10 + d) % x
                trans[i][new_mod] = (trans[i][new_mod] + count[d]) % MOD

    # Raise matrix to the power of b
    final = matrix_pow(trans, b, x)

    # Answer is the number of ways to reach k mod x
    print(final[0][k])

solve()
