def solve():
    n, m, k = map(int, input().split())
    a = list(map(int, input().split()))

    # Build adjacency matrix for rules
    c = [[0] * n for _ in range(n)]
    for _ in range(k):
        x, y, val = map(int, input().split())
        x -= 1  # Convert to 0-indexed
        y -= 1
        c[x][y] = val

    # dp[mask][last] = max satisfaction for dishes in mask, ending with last dish
    # mask: integer bitmask of size n
    # last: integer index of last dish eaten
    dp = [[-1] * n for _ in range(1 << n)]

    # Initialize: start with each dish individually
    for i in range(n):
        dp[1 << i][i] = a[i]

