def solve():
    s = input().strip()
    t = input().strip()
    n = len(t)
    m = len(s)

    # dp[i] = max prefix length of t we can match using s[0..i]
    dp = [0] * m
    curr = 0
    for i in range(m):
        if t[curr] == s[i]:
            dp[i] = dp[i-1] + 1 if i > 0 else 1
            curr += 1
            if curr == n:
                curr = n
        else:
            dp[i] = dp[i-1] if i > 0 else 0

    # suffix[i] = max suffix length of t that can be matched starting at or after i
    suffix = [0] * (m + 1)
    curr = n - 1  # index of last character
    for i in range(m - 1, -1, -1):
        if t[curr] == s[i]:
            suffix[i] = suffix[i + 1] + 1
            curr -= 1
            if curr < 0:
                break
        else:
            suffix[i] = suffix[i + 1]

    ans = 0
    # For each prefix length k (0..n-1), find best suffix start
    for k in range(n):
        # suffix start is the first index where t[k+1..n-1] can be matched
        start = suffix[k + 1]  # suffix starts at start
        # We can remove [l..m-1] where l <= start and dp[l-1] >= k+1
        l = 0
        while l < start:
            if dp[l] >= k + 1:
                break
            l += 1
        if l < start:
            ans = max(ans, m - l)

    print(ans)

solve()
