import sys

def solve(a, b):
    """Find the sum of all nice integers x.
    Positive integer x is nice if:
    - There exists some k in [1, a] such that k // x + k % x == b
    - And there exists some m in [1, a] such that x // m + x % m == b
    """
    nice_numbers = set()

    # Find all numbers that can be divided into parts summing to b
    for k in range(1, a + 1):
        for q in range(0, b + 1):
            r = b - q
            if r < 0:
                break
            # k = q * x + r, so x = (k - r) // q if q > 0
            if q == 0:
                continue
            if k - r < 0:
                continue
            x = (k - r) // q
            nice_numbers.add(x)

    # Check which of these are nice
    total = 0
    for x in nice_numbers:
        # Check if there exists m in [1, a] such that x // m + x % m == b
        has_valid_m = False
        for m in range(1, a + 1):
            if x // m + x % m == b:
                has_valid_m = True
                break
        if has_valid_m:
            total += x

    return total

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    a, b = map(int, data)
    MOD = 1000000007
    print(solve(a, b) % MOD)

if __name__ == "__main__":
    main()
"}

