    it = iter(data)

    n = int(next(it))
    m = int(next(it))
    q = int(next(it))

    p = []
    for _ in range(n):
        p.append(int(next(it)))

    a = []
    for _ in range(m):
        a.append(int(next(it)))

    # Precompute next occurrence of each value
    next_pos = [0] * (m + 1)
    for i in range(m - 1, -1, -1):
        next_pos[a[i]] = i + 1

    # Precompute for each position in a, the next position of each value
    next_pos_arr = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m, 0, -1):
        for v in range(1, n + 1):
            next_pos_arr[i][v] = next_pos[a[i - 1]] if a[i - 1] == v else next_pos_arr[i + 1][v]

    # For each query, check if we can form any cyclic shift of p
    result = []
    for _ in range(q):
        l = int(next(it))
        r = int(next(it))

        # Use DP to check if we can form any cyclic shift of p
        # dp[i] = minimum position in a to form first i elements of a cyclic shift
        dp = [float('inf')] * (n + 1)
        dp[0] = l - 1  # 0-based indexing

        for i in range(1, n + 1):
            if dp[i - 1] == float('inf'):
