        if num % 2 == 0:
            evens.append(num)
        else:
            odds.append(num)

    # If there are both evens and odds, we can sort and interleave optimally
    if evens and odds:
        evens.sort()
        odds.sort()

        # Create result array by interleaving
        result = []
        e_idx = o_idx = 0

        # Place the smallest number first (this is always the smallest among the two first elements)
        if evens[0] < odds[0]:
            result.append(evens[0])
            e_idx += 1
        else:
            result.append(odds[0])
            o_idx += 1

        # Fill the rest
        while e_idx < len(evens) or o_idx < len(odds):
            if e_idx < len(evens) and (o_idx >= len(odds) or evens[e_idx] <= odds[o_idx]):
                result.append(evens[e_idx])
                e_idx += 1
            else:
                result.append(odds[o_idx])
                o_idx += 1
    else:
        # If only evens or only odds, we cannot rearrange
        result = a

    print(' '.join(map(str, result)))

