    while True:
        # Find all possible absolute differences
        new_elements = set()
        elements = sorted(current)

        for i in range(len(elements)):
            for j in range(i + 1, len(elements)):
                diff = abs(elements[i] - elements[j])
                if diff not in current:
                    new_elements.add(diff)

        if not new_elements:
