n, r = map(int, input().split())

# Generate all integer points within or on the circle of radius r
points = []
for x in range(-r, r + 1):
    for y in range(-r, r + 1):
        if x*x + y*y <= r*r:
            points.append((x, y))

max_sum = 0
optimal_positions = []

# Try placing all n towers at the same point (this gives sum 0)
sum_sq = 0
for i in range(n):
    for j in range(n):
        sum_sq += (0 - 0)**2 + (0 - 0)**2
max_sum = sum_sq
optimal_positions = [(0, 0)] * n

# Try placing towers at the points that maximize spread
# For even n, place n/2 pairs of opposite points
# For odd n, place (n-1)/2 pairs of opposite points, and one point at a different location

# Find opposite points
opposite_points = []
for point in points:
    x, y = point
    opposite = (-x, -y)
    if opposite not in points:
        continue
    if opposite not in opposite_points:
        opposite_points.append((point, opposite))

if len(opposite_points) >= n // 2:
    # Place n/2 pairs of opposite points
    positions = []
    for i in range(n // 2):
        positions.append(opposite_points[i][0])
        positions.append(opposite_points[i][1])

    sum_sq = 0
    for i in range(n):
        for j in range(n):
            dx = positions[i][0] - positions[j][0]
            dy = positions[i][1] - positions[j][1]
            sum_sq += dx*dx + dy*dy

    if sum_sq > max_sum:
        max_sum = sum_sq
        optimal_positions = positions

# Output the result
print(max_sum)
for x, y in optimal_positions:
    print(x, y)
