import math

n, r = map(int, input().split())

# Generate all integer points within or on the circle of radius r
points = []
for x in range(-r, r + 1):
    for y in range(-r, r + 1):
        if x*x + y*y <= r*r:
            points.append((x, y))

# Find points in all 8 octants (excluding origin for now)
first_octant = []
for x in range(1, r + 1):
    for y in range(1, r + 1):
        if x*x + y*y <= r*r:
            first_octant.append((x, y))

# Generate all points by mirroring
all_points = []
for point in first_octant:
    all_points.append(point)
    all_points.append((-point[0], point[1]))
    all_points.append((point[0], -point[1]))
    all_points.append((-point[0], -point[1]))

# Add origin
all_points.append((0, 0))

# Try all possible combinations
max_sum = 0
optimal_positions = []

# Try placing n towers at the same point
sum_sq = 0
for i in range(n):
    for j in range(n):
        sum_sq += (0 - 0)**2 + (0 - 0)**2
max_sum = sum_sq
optimal_positions = [(0, 0)] * n

# Try placing n towers at different points
# The optimal is to spread them out as much as possible
for points_subset in itertools.combinations(all_points, n):
    sum_sq = 0
    for i in range(n):
        for j in range(n):
            dx = points_subset[i][0] - points_subset[j][0]
            dy = points_subset[i][1] - points_subset[j][1]
            sum_sq += dx*dx + dy*dy

    if sum_sq > max_sum:
        max_sum = sum_sq
        optimal_positions = list(points_subset)

print(max_sum)
for x, y in optimal_positions:
    print(x, y)
