def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []

    for _ in range(t):
        n = int(next(it))
        s = next(it)

        # Pattern 01: 0, 1, 0, 1, ...
        # Count groups of '1'
        cnt01 = 0
        prev = '0'
        for ch in s:
            if ch == prev:
                continue
            else:
                if ch == '1':
                    cnt01 += 1
                prev = ch

        # Pattern 10: 1, 0, 1, 0, ...
        # Count groups of '0'
        cnt10 = 0
        prev = '1'
        for ch in s:
            if ch == prev:
                continue
            else:
                if ch == '0':
                    cnt10 += 1
                prev = ch

        out_lines.append(str(min(cnt01, cnt10)))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
