def min_university_hours(n, m, k):
    # Read timetable
    timetable = [input().strip() for _ in range(n)]

    # DP: dp[i][j] = minimum hours for first i days with j skipped lessons
    dp = [[float('inf')] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for day_idx in range(n):
        # Find all lesson positions for this day (0-indexed)
        lessons = [i for i, ch in enumerate(timetable[day_idx]) if ch == '1']
        if not lessons:
            # No lessons on this day
            for j in range(k + 1):
                dp[day_idx + 1][j] = dp[day_idx][j]
            continue

        first_lesson = lessons[0]
        last_lesson = lessons[-1]

        # For each possible number of skipped lessons on this day
        for skip_before in range(first_lesson + 1):
            for skip_after in range(last_lesson + 1):
                skipped = skip_before + skip_after
                if skipped > k:
                    continue

                # The time spent on this day
                time_spent = last_lesson - first_lesson + 1

                # Update DP
                for prev_skipped in range(k - skipped + 1):
                    if dp[day_idx][prev_skipped] != float('inf'):
                        dp[day_idx + 1][prev_skipped + skipped] = min(
                            dp[day_idx + 1][prev_skipped + skipped],
                            dp[day_idx][prev_skipped] + time_spent
                        )

    return min(dp[n][j] for j in range(k + 1))

# Read input
n, m, k = map(int, input().split())

# Compute and print result
print(min_university_hours(n, m, k))
