    for i in range(n):
        dp[(1 << i, i)] = a[i]

    for mask in range(1 << n):
        for last in range(n):
            state = (mask, last)
            if state not in dp:
                continue

            # Try adding a new dish
            for i in range(n):
                if not (mask & (1 << i)):  # Dish i not yet eaten
                    new_mask = mask | (1 << i)
                    new_satisfaction = dp[state] + a[i]

                    # Check if there's a bonus rule for last before i
                    if (last, i) in rules:
                        new_satisfaction += rules[(last, i)]

                    new_state = (new_mask, i)
                    if new_satisfaction > dp.get(new_state, INF):
