                pos = (pos[0] - 1, pos[1])
            elif c == 'R':
                pos = (pos[0] + 1, pos[1])
            elif c == 'D':
                pos = (pos[0], pos[1] - 1)
            elif c == 'U':
                pos = (pos[0], pos[1] + 1)
            visited.add(pos)

        # Check each visited position as potential obstacle
        found = False
        for (ox, oy) in visited:
            if ox == 0 and oy == 0:
                continue  # Can't place obstacle at starting position

            # Simulate with obstacle at (ox, oy)
            robot_pos = (0, 0)
            for c in s:
                nx, ny = robot_pos
                if c == 'L':
                    nx -= 1
                elif c == 'R':
                    nx += 1
                elif c == 'D':
                    ny -= 1
                elif c == 'U':
                    ny += 1

                # Check if the next position is the obstacle
                if (nx, ny) == (ox, oy):
                    # Obstacle is present, stay in place
                    robot_pos = (robot_pos[0], robot_pos[1])
                else:
                    robot_pos = (nx, ny)

            if robot_pos == (0, 0):
