# Find all lucky numbers (only digits 4 and 7)
def is_lucky(w):
    s = str(w)
    for ch in s:
        if ch not in ('4', '7'):
            return False
    return True

# Build graph and find components based on lucky edges
from collections import defaultdict, deque

g = defaultdict(list)

for _ in range(n - 1):
    u, v, w = map(int, input().split())
    if is_lucky(w):
        g[u].append(v)
        g[v].append(u)

# Find components based on lucky edges
visited = [False] * (n + 1)
components = []

for i in range(1, n + 1):
    if not visited[i]:
        q = deque([i])
        visited[i] = True
        component = []
        while q:
            node = q.popleft()
            component.append(node)
            for neighbor in g[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    q.append(neighbor)
        components.append(component)

# Calculate answer
