import sys

def run_query(s: str, l: int, r: int) -> str:
    """Run the query on the substring s[l-1:r]"""
    seq = list(s[l-1:r])
    cp = 0  # current pointer
    dp = 1  # direction pointer: 1 for right, -1 for left
    counts = [0] * 10

    while 0 <= cp < len(seq):
        ch = seq[cp]

        if ch.isdigit():
            digit = int(ch)
            counts[digit] += 1

            # Move CP first
            cp += dp

            # Decrease the digit in the original position
            if digit > 0:
                seq[cp - dp] = str(digit - 1)
            else:
                # Erase the position
                seq[cp - dp:cp - dp + 1] = []

                # If we erased, we need to adjust CP if it's after the erased position
                if cp - dp == 0:
                    cp = 0
                elif cp - dp == len(seq) - 1:
                    cp = len(seq) - 1
                else:
                    cp = cp - 1
        elif ch == '<':
            dp = -1  # left
            cp += dp

            # If the new character is also '<' or '>', erase the previous character
            if cp >= 0 and cp < len(seq):
                new_ch = seq[cp]
                if new_ch in ['<', '>']:
                    seq[cp - dp:cp - dp + 1] = []

                    # Adjust CP if it's after the erased position
                    if cp - dp == 0:
                        cp = 0
                    elif cp - dp == len(seq) - 1:
                        cp = len(seq) - 1
                    else:
                        cp = cp - 1
        elif ch == '>':
            dp = 1  # right
            cp += dp

            # If the new character is also '<' or '>', erase the previous character
            if cp >= 0 and cp < len(seq):
                new_ch = seq[cp]
                if new_ch in ['<', '>']:
                    seq[cp - dp:cp - dp + 1] = []

                    # Adjust CP if it's after the erased position
                    if cp - dp == 0:
                        cp = 0
                    elif cp - dp == len(seq) - 1:
                        cp = len(seq) - 1
                    else:
                        cp = cp - 1

    return ' '.join(map(str, counts))

# Read input
input_lines = sys.stdin.read().strip().split('\n')
n, q = int(input_lines[0].split()[0]), int(input_lines[0].split()[1])
s = input_lines[1]
queries = []
for line in input_lines[2:2+q]:
    l, r = int(line.split()[0]), int(line.split()[1])
    queries.append((l, r))

# Process each query
results = []
for l, r in queries:
    result = run_query(s, l, r)
    results.append(result)

# Print results
print('\n'.join(results))
