# Function to simulate the interpreter
def simulate(s):
    chars = list(s)
    cp = 0
    dp = 1  # right
    counts = [0] * 10

    while 0 <= cp < len(chars):
        if chars[cp].isdigit():
            # Print the digit
            digit = int(chars[cp])
            counts[digit] += 1

            # Move CP
            if dp == 1:
                cp += 1
            else:
                cp -= 1

            # Decrease the digit or erase if 0
            if digit == 0:
                # Erase this character
                del chars[cp]
            else:
                if 0 <= cp < len(chars):
                    chars[cp] = str(digit - 1)
        else:  # '<' or '>'
            # Change direction
            if chars[cp] == '<':
                dp = 0
            else:
                dp = 1

            # Move CP
            if dp == 1:
                cp += 1
            else:
                cp -= 1

            # Check if the new character is '<' or '>'
            if 0 <= cp < len(chars) and chars[cp] in ['<', '>']:
                # Erase the previous character
                if dp == 1:
                    if cp - 1 >= 0:
                        del chars[cp - 1]
                else:
                    if cp + 1 < len(chars):
                        del chars[cp + 1]

    return counts

for l, r in queries:
    subseq = sequence[l-1:r]
