def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))

    # Read points
    points = []
    for _ in range(n):
        x = int(next(it))
        y = int(next(it))
        points.append((x, y))

    # Read w sequence
    w = [int(next(it)) for _ in range(n)]

    # For each possible s value, store points with that s
    s_points = {}  # key: s, value: list of (x, y) points
    for x, y in points:
        s = y - x
        if s not in s_points:
            s_points[s] = []
        s_points[s].append((x, y))

    # Sort w sequence by s descending, then by position (to maintain original order within same s?)
    w_sorted = []
    for i, s in enumerate(w):
        w_sorted.append((s, i))
    w_sorted.sort(key=lambda x: (-x[0], x[1]))

    # Sort points by s descending, then by x descending (to ensure consistent order within same s)
    points_sorted = []
    for s in sorted(s_points.keys(), reverse=True):
        for p in sorted(s_points[s], key=lambda x: (-x[0], -x[1])):
            points_sorted.append(p)

    # Assign points to positions based on sorted w sequence
    assigned = [False] * len(points_sorted)
    out = []

    for s, pos_idx in w_sorted:
        for i, point in enumerate(points_sorted):
            if not assigned[i] and (point[1] - point[0]) == s:
                out.append(point)
                assigned[i] = True
                break

    if len(out) == n:
        print("YES")
        for p in out:
            print(f"{p[0]} {p[1]}")
    else:
        print("NO")

