    # Find all connected pixels of the same color
    visited = [[False]*len(grid[0]) for _ in range(len(grid))]
    stack = [(top, left)]
    visited[top][left] = True
    while stack:
        i, j = stack.pop()
        if i < top or i > bottom or j < left or j > right:
            # Pixel outside current block
            return None
        if grid[i][j] == color:
            for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
                ni, nj = i+di, j+dj
                if not visited[ni][nj] and grid[ni][nj] == color:
                    visited[ni][nj] = True
                    stack.append((ni, nj))
        else:
            # Border of the block
            return (i, j)
    return (top, left)  # No border found, return top-left

def solve():
    m, n = map(int, input().split())
    grid = [input().strip() for _ in range(m)]

    # Find initial block (containing (0,0))
    visited = [[False]*len(grid[0]) for _ in range(len(grid))]
    stack = [(0, 0)]
    visited[0][0] = True
    while stack:
        i, j = stack.pop()
        if grid[i][j] == '0':
            continue
        for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
            ni, nj = i+di, j+dj
            if 0 <= ni < len(grid) and 0 <= nj < len(grid[0]) and not visited[ni][nj] and grid[ni][nj] != '0':
                visited[ni][nj] = True
                stack.append((ni, nj))

    # Find the rectangle of the initial block
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if visited[i][j] and grid[i][j] != '0':
                top = bottom = i
                left = right = j
                while top > 0 and grid[top-1][j] != '0':
                    top -= 1
                while bottom < len(grid)-1 and grid[bottom+1][j] != '0':
                    bottom += 1
                while left > 0 and grid[i][left-1] != '0':
                    left -= 1
                while right < len(grid[0])-1 and grid[i][right+1] != '0':
                    right += 1
                if top == 0 and left == 0:
