        if top == 0 and left == 0:
            break

    # Simulate steps
    steps = 0
    # State: (top, left, bottom, right, DP, CP)
    # DP: 0=right, 1=left, 2=up, 3=down
    # CP: 0=left, 1=right
    state = (top, left, bottom, right, 0, 0)
    seen = {}

    while steps < n:
        # Find the furthest edge in DP direction
        # and the furthest pixel in CP direction
