        line = sys.stdin.readline()
        if line.strip() == '':
            continue
        numbers.append(int(line.strip()))

    # Initialize sheets
    sheets = [0] * n

    # Fill the sheets from left to right
    for i in range(n):
        pi = numbers[i]
        sheets[i] = pi

        # Check if we've completed and won
        if all(s > 0 for s in sheets):
            if all(sheets[i] <= sheets[i + 1] for i in range(n - 1)):
                print(i + 1)  # 1-indexed
                sys.stdout.flush()
                return

    # For remaining numbers, find the best position
    for i in range(n, m):
        pi = numbers[i]
        best_pos = -1

        # Try to find a position that maintains non-decreasing order
        for j in range(n):
            if sheets[j] == 0:
                # Empty position, can place here
                best_pos = j
                break
            else:
                # Non-empty position, check if we can maintain order
                if pi >= sheets[j - 1] and pi <= sheets[j]:
                    best_pos = j
                    break
                elif pi < sheets[j - 1]:
                    # Can't maintain order
                    pass
                elif pi > sheets[j]:
                    best_pos = j
                    break

        # If no position found, replace rightmost possible
        if best_pos == -1:
            for j in range(n - 1, -1, -1):
                if pi >= sheets[j - 1] and pi <= sheets[j]:
