import sys
from collections import deque

def main():
    # Read the first line for dimensions
    while True:
        line = sys.stdin.readline()
        if not line:
            break
        if line.strip() != '':
            break
    dims = line.strip().split()
    k, n, m = map(int, dims)

    # Read the grid
    grid = []
    for layer in range(k):
        # Skip any empty lines
        while True:
            line = sys.stdin.readline()
            if not line:
                break
            if line.strip() != '':
                break

        # Read n lines for this layer
        layer_grid = []
        for row in range(n):
            while True:
                line = sys.stdin.readline()
                if not line:
                    break
                if line.strip() != '':
                    break
            layer_grid.append(line.strip())
        grid.append(layer_grid)

    # Read the starting position
    while True:
        line = sys.stdin.readline()
        if not line:
            break
        if line.strip() != '':
            break
    x, y = map(int, line.strip().split())

    # Convert to 0-indexed
    start_k = 0  # first layer is index 0
    start_x = x - 1
    start_y = y - 1

    # BFS to find all reachable cells
    visited = [[[False for _ in range(m)] for _ in range(n)] for _ in range(k)]
    queue = deque()

    # Find the starting cell
    for i in range(k):
        for j in range(n):
            for l in range(m):
                if grid[i][j][l] == '.' and i == start_k and j == start_x and l == start_y:
                    queue.append((i, j, l))
                    visited[i][j][l] = True
                    break

    while queue:
        i, j, l = queue.popleft()

        # Check all 6 directions
        directions = [
            (-1, 0, 0), (1, 0, 0),  # up/down
            (0, -1, 0), (0, 1, 0),  # left/right
            (0, 0, -1), (0, 0, 1)   # front/back
        ]

        for di, dj, dl in directions:
            ni, nj, nl = i + di, j + dj, l + dl

            if 0 <= ni < k and 0 <= nj < n and 0 <= nl < m:
                if grid[ni][nj][nl] == '.' and not visited[ni][nj][nl]:
                    visited[ni][nj][nl] = True
                    queue.append((ni, nj, nl))

    # Count all filled cells (all reachable '.' cells)
    filled = 0
    for i in range(k):
        for j in range(n):
            for l in range(m):
                if grid[i][j][l] == '.' and visited[i][j][l]:
                    filled += 1

    print(filled)

if __name__ == "__main__":
    main()
