def count_digit(d):
    """Count occurrences of digit d in the block"""
    return digits.count(d)

# Build transition matrix for one block
T = [[0] * x for _ in range(x)]
for i in range(x):
    for d in range(1, 10):
        cnt = count_digit(d)
        if cnt > 0:
            new_state = (i * 10 + d) % x
            T[i][new_state] += cnt

# Raise transition matrix to power b
def matrix_mult(a, b):
    """Matrix multiplication"""
    result = [[0] * x for _ in range(x)]
    for i in range(x):
        for k2 in range(x):
            if a[i][k2] == 0:
                continue
            for j in range(x):
                result[i][j] = (result[i][j] + a[i][k2] * b[k2][j]) % 1000000007
    return result

def matrix_pow(mat, power):
    """Matrix exponentiation"""
    result = [[0] * x for _ in range(x)]
    for i in range(x):
        result[i][i] = 1  # Identity matrix

    while power > 0:
        if power % 2 == 1:
            result = matrix_mult(result, mat)
        mat = matrix_mult(mat, mat)
        power //= 2
    return result

