def sum_squared_distances(points):
    """Calculate the sum of squared distances between all pairs of points"""
    n = len(points)
    total = 0

    for i in range(n):
        for j in range(i + 1, n):
            dx = points[i][0] - points[j][0]
            dy = points[i][1] - points[j][1]
            total += dx * dx + dy * dy

    return total

def solve():
    n, r = map(int, input().split())

    # Get all integer points within the circle of radius r
    points = []
    for x in range(-r, r + 1):
        for y in range(-r, r + 1):
            if x*x + y*y <= r*r:
                points.append((x, y))

    # Try to place points to maximize sum
    # Start with one point at (r, 0)
    final_points = [(r, 0)]

    # For each additional point, place it to maximize the sum
    for _ in range(n - 1):
        best = None
        best_sum = 0

        # Try all possible remaining points
        for point in points:
            if point != (r, 0):  # Already placed one point at (r, 0)
                # Calculate new sum with this point
                new_sum = 0
                for placed in final_points:
                    dx = placed[0] - point[0]
                    dy = placed[1] - point[1]
                    new_sum += dx * dx + dy * dy

                # Compare with best
                if new_sum > best_sum:
                    best = point
                    best_sum = new_sum

        # Place the best point
        final_points.append(best)

    # Output
    print(sum_squared_distances(final_points))
    for point in final_points:
        print(point[0], point[1])

if __name__ == "__main__":
