queries = []
for _ in range(q):
    l, r = map(int, input().split())
    queries.append((l, r))

# Simulate for each query
results = []
for l, r in queries:
    seq = list(s[l-1:r])
    print_counts = [0] * 10
    cp = 0  # current pointer
    dp_right = True  # direction pointer

    while 0 <= cp < len(seq):
        ch = seq[cp]

        if ch.isdigit():
            digit = int(ch)
            print_counts[digit] += 1

            # Move CP according to DP
            if dp_right:
                cp += 1
            else:
                cp -= 1

            # Decrease the digit by 1
            if digit > 0:
                seq[cp] = str(digit - 1)
            else:
                # Erase the character
                del seq[cp]

                # After deletion, we need to adjust cp
                if dp_right:
                    cp -= 1

        else:  # '<' or '>'
            # Update direction
            if ch == '<':
                dp_right = False
            else:
                dp_right = True

            # Move CP according to DP
            if dp_right:
                cp += 1
            else:
                cp -= 1

            # Check if new character is '<' or '>'
            if cp >= 0 and cp < len(seq):
                new_ch = seq[cp]
                if new_ch in ['<', '>']:
                    # Erase the previous character
                    if dp_right:
                        cp -= 1
                    else:
                        cp += 1
                    del seq[cp]

                    # Adjust cp after deletion
                    if dp_right:
                        cp -= 1
                    else:
                        cp += 1

    results.append(tuple(print_counts))

# Print results
for counts in results:
    print(' '.join(map(str, counts)))
