import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n, m, min_t, max_t = map(int, data[:4])
    temps = list(map(int, data[4:4+m]))

    # Check if all temps within [min, max]
    for t in temps:
        if t < min_t or t > max_t:
            print("Incorrect")
            return

    has_min = any(t == min_t for t in temps)
    has_max = any(t == max_t for t in temps)

    if not has_min and not has_max:
        if n - m >= 2:
            print("Correct")
        else:
            print("Incorrect")
    else:
        print("Correct")

if __name__ == "__main__":
    solve()
